/**
 * Countdown's states fixture, with the React fixture's entry names, so a
 * contract's `when <state>` names the same entry in both shells.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/countdown.ts`. Never edit it by hand.
 */
import { h, reactive } from 'vue'

import type { ComponentStates } from '@polymorph/vue'

import Button from '../controls/Button.vue'
import Countdown from './Countdown.vue'
import Inline from '../layout/Inline.vue'
import Text from './Text.vue'

export const states: ComponentStates = {
  component: 'Countdown',
  entries: [
    {
      name: 'minutes — m:ss',
      render: (overrides = {}) =>
        h(Countdown, {
          until: new Date(Date.now() + 299_000).toISOString(),
          label: 'Time until the code expires',
          ...overrides,
        }),
      expect: { 'data-ended': null },
    },
    {
      name: 'hours — h:mm:ss from an hour',
      render: (overrides = {}) =>
        h(Countdown, {
          until: new Date(Date.now() + 3_725_000).toISOString(),
          label: 'Time until the session ends',
          ...overrides,
        }),
    },
    {
      name: 'ended — 0:00 once the moment is reached',
      render: (overrides = {}) =>
        h(Countdown, {
          until: new Date(Date.now() - 5_000).toISOString(),
          label: 'Time until the code expires',
          ...overrides,
        }),
      expect: { 'data-ended': '' },
    },
    {
      name: 'locale — the locale’s numerals and words',
      render: (overrides = {}) =>
        h(Countdown, {
          until: new Date(Date.now() + 299_000).toISOString(),
          label: 'Time until the code expires',
          locale: 'ar-EG',
          ...overrides,
        }),
    },
    {
      name: 'announced — a polite line at one minute and at ten seconds',
      render: (overrides = {}) =>
        h(Countdown, {
          until: new Date(Date.now() + 65_000).toISOString(),
          label: 'Time until the code expires',
          announce: true,
          ...overrides,
        }),
    },
    {
      name: 'beside a Button — the application enables it at the end',
      render: () =>
        h({
          setup() {
            const held = reactive({
              locked: true,
              until: new Date(Date.now() + 30_000).toISOString(),
            })
            return () => [
              h(
                Inline,
                { gap: 3, align: 'center' },
                {
                  default: () => [
                    h(
                      Text,
                      {},
                      {
                        default: () => [
                          'Send a new code in ',
                          h(Countdown, {
                            until: held.until,
                            label: 'Time until a new code can be sent',
                            onEnd: () => {
                              held.locked = false
                            },
                          }),
                        ],
                      },
                    ),
                    h(Button, {
                      variant: 'outline',
                      tone: 'neutral',
                      size: 'sm',
                      label: 'Send a new code',
                      disabled: held.locked,
                    }),
                  ],
                },
              ),
            ]
          },
        }),
    },
    {
      name: 'invalid — no moment, so nothing renders',
      render: (overrides = {}) =>
        h(Countdown, { until: 'not-a-moment', label: 'Time until the code expires', ...overrides }),
      rendersNothing: true,
    },
  ],
}
